-- ----------------------------
-- Table structure for wiki_doc
-- ----------------------------
DROP TABLE IF EXISTS `wiki_doc`;
CREATE TABLE `wiki_doc`  (
  `id` bigint(20) NOT NULL,
  `space_id` bigint(20) NOT NULL COMMENT '所属空间',
  `parent_id` bigint(20) NULL DEFAULT 0 COMMENT '父文档，0=根',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Markdown 正文',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `sort` int(11) NULL DEFAULT 0,
  `public_read` tinyint(4) NULL DEFAULT NULL COMMENT 'NULL=跟随空间，0-私有，1-公开可读',
  `author_id` bigint(20) NULL DEFAULT NULL,
  `author_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL,
  `create_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_time` datetime NOT NULL,
  `update_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '0-删除，1-有效',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_space_parent`(`space_id` ASC, `parent_id` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_space_title`(`space_id` ASC, `title` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '知识库文档' ROW_FORMAT = Dynamic;

