INSERT INTO `wiki_doc` VALUES (2115147253255680005, 2115145719482593281, 2115147253255680004, 'overview', '# 代码生成（codegen）\n\n| 更新时间 | 2026-10-27 |\n|----------|------------|\n| 路径 | `cloudwaer-integration-serve/cloudwaer-codegen/` |\n| 库 | `cloudwaer_codegen_config` |\n| 前端 | `views/codegen/{CodeGenerator,DatabaseConnection}.vue` + 连接弹窗 |\n\n## 1. 职责\n\n- 连接数据库、配置表与模板、生成 Entity/Mapper/Service/Controller 等\n- 权限码风格 `codegen:*`（如 `codegen:generator:preview`）；三方一致见 [../rbac/overview.md](../rbac/overview.md)\n\n## 2. 运行\n\n- 单体：boot 多数据源路由 `/codegen/**` → codegen 库\n- 微服务：独立 serve + 网关路由，无 StripPrefix\n\n## 3. 注意\n\n- 前端已无 api-scanner 相关页面；后端公共模块是否保留以仓库当前代码为准\n- 生成物落入业务模块时遵守包路径与格式化（spring-javaformat）\n\n## 4. 变更记录\n\n| 日期 | 说明 |\n|------|------|\n| 2026-10-27 | 初版 |\n', '# 代码生成（codegen） | 更新时间 | 2026-10-27 | |----------|------------| | 路径 | `cloudwaer-integration-serve/cloudwaer-codegen/` | | 库 | `cloudwaer_codegen_config` | | 前端 | `views/codegen/{CodeGenerator,Databa', 0, NULL, 1, 'admin', '2026-10-28 02:22:57', NULL, '2026-10-28 02:22:57', NULL, 1);
