INSERT INTO `wiki_doc` VALUES (2115147253322788868, 2115145719482593281, 2115147253322788867, 'controllers', '# Flowable 控制器与权限\n\n| 更新时间 | 2026-10-27 |\n|----------|------------|\n| 路径 | `cloudwaer/cloudwaer-integration-serve/cloudwaer-flowable/` |\n| 版本 | Flowable **7.0.1** |\n| 库 | `cloudwaer_flowable`（引擎 + `wf_*`） |\n\n## 1. 控制器前缀（前端必须带 `/flowable`）\n\n| 前缀 | 职责 | 代表权限码 |\n|------|------|------------|\n| `/flowable/model` | 模型 CRUD/发布/回滚 | `flowable:model:*` |\n| `/flowable/definition` | 可申请定义 | `flowable:process:definitions` |\n| `/flowable/process` | 启动/实例监控/历史/图 | `flowable:process:*`、`flowable:monitor:*` |\n| `/flowable/task` | 待办/已办/认领/完成 | `flowable:task:*` |\n| `/flowable/node-action` | 节点动作配置 | `flowable:node:action:*` |\n| `/flowable/bpmn-deploy` | BPMN 部署/提取/校验 | `flowable:bpmn:*`、`flowable:designer:validate` |\n\n## 2. 启动与配置\n\n- 微服务：`FlowableServeApplication`，端口见 bootstrap（曾为 4343）\n- boot 内嵌：`cloudwaer-flowable-serve`；`async-executor-activate: false`、`idm.enabled: false`、`database-schema-update: update`\n- 数据源：必须路由到 flowable 库（见 [../platform/architecture.md](../platform/architecture.md)）\n\n## 3. 扩展表\n\n`WfModel`、`WfNodeAction`、`WfProcessExt`、`WfTaskExt` 等；全量见 `db/cloudwaer_flowable.sql`。\n\n## 4. 节点动作\n\n- `WfNodeAction` + `ActionDispatcher`：`log` / `notify` / `http`\n- Listener Bean 名：`flowableTaskListener` / `flowableExecutionListener`\n- 当前用户：`SecurityContextUtil.getCurrentUsername()`（勿另造 userId 体系）\n\n## 5. 启动流程依赖\n\n`startProcess` 按 `processDefinitionKey` 查最新 `wf_model`；缺模型或未配 `endTime` 直接业务异常；`dueTime` 不得晚于模型 `endTime`。\n\n## 6. 变更记录\n\n| 日期 | 说明 |\n|------|------|\n| 2026-10-27 | 初版 |\n', '# Flowable 控制器与权限 | 更新时间 | 2026-10-27 | |----------|------------| | 路径 | `cloudwaer/cloudwaer-integration-serve/cloudwaer-flowable/` | | 版本 | Flowable **7.0.1** | | 库 | `cloudwaer_flowable`（引擎 + `wf_*', 0, NULL, 1, 'admin', '2026-10-28 02:22:57', NULL, '2026-10-28 02:22:57', NULL, 1);
INSERT INTO `wiki_doc` VALUES (2115147253389897729, 2115145719482593281, 2115147253322788867, 'designer-and-pitfalls', '# Flowable 设计器与坑位\n\n| 更新时间 | 2026-10-27 |\n|----------|------------|\n\n## 1. 前端\n\n| 项 | 说明 |\n|----|------|\n| 技术栈 | `bpmn-js` + `views/flowable/bpmn/translate.ts` |\n| 页面 | `views/flowable/{ModelManagement,ProcessApplication,ProcessMonitor,TaskManagement,ProcessDesigner,ProcessTest}.vue` |\n| 节点配置 | `components/flowable/NodeActionConfig.vue` |\n| API | `src/api/flowable.ts` — **全部 URL 必须 `/flowable/...`** |\n\n## 2. 网关路由\n\n- 动态路由来自 `sys_gateway_route`\n- **禁止 StripPrefix**（否则服务收到 `/model/list` 全量 404）\n- 控制器与前端均使用完整 `/flowable/**`\n\n## 3. 菜单种子\n\n- 启用：`flowable:model` / `application:view` / `monitor:view` / `task:view`\n- `flowable:*:route` 三行 `enabled=0` 重复页**勿授给角色**（前端重复菜单）\n\n## 4. 已知坑\n\n| 坑 | 处理 |\n|----|------|\n| 重复文件 `views/Processdesigner.vue` vs `views/flowable/ProcessDesigner.vue` | ModelManagement 用后者；改设计器先确认引用 |\n| 示例 BPMN XSD 挡 boot | `--flowable.check-process-definitions=false` |\n| typecheck | 设计器大页已 exclude；仍有 admin/flowable 遗留 |\n\n## 5. 变更记录\n\n| 日期 | 说明 |\n|------|------|\n| 2026-10-27 | 初版 |\n', '# Flowable 设计器与坑位 | 更新时间 | 2026-10-27 | |----------|------------| ## 1. 前端 | 项 | 说明 | |----|------| | 技术栈 | `bpmn-js` + `views/flowable/bpmn/translate.ts` | | 页面 | `views/flowable/{ModelManagement,Pro', 0, NULL, 1, 'admin', '2026-10-28 02:22:57', NULL, '2026-10-28 02:22:57', NULL, 1);
INSERT INTO `wiki_doc` VALUES (2115147253389897730, 2115145719482593281, 2115147252798500865, 'login-auth-whitepaper', '# 文档已迁移\n\n本文件仅为跳转占位。请阅读：\n\n- **[auth/login-auth.md](auth/login-auth.md)** — 登录认证业务白皮书\n\n新文档一律按模块写入 `doc/{模块名}/`，不要再在 `doc/` 根目录追加业务文档。总索引见 [README.md](README.md)。\n', '# 文档已迁移 本文件仅为跳转占位。请阅读： - **[auth/login-auth.md](auth/login-auth.md)** — 登录认证业务白皮书 新文档一律按模块写入 `doc/{模块名}/`，不要再在 `doc/` 根目录追加业务文档。总索引见 [README.md](README.md)。', 12, NULL, 1, 'admin', '2026-10-28 02:22:57', NULL, '2026-10-28 03:32:14', NULL, 1);
